const dive = (headingZh, headingEn, bodyZh, bodyEn, citations) => [{ heading: pair(headingZh, headingEn), body: pair(bodyZh, bodyEn), citations }];

export const expansionBlogEnhancements = {
  'find-local-market-creators': {
    deepDive: dive('用受众交叉验证代替“所在地”推断', 'Replace location assumptions with audience cross-checks', 'TikTok Audience Insights 可以按受众兴趣、行为和人口特征探索人群，但官方也说明这些洞察是聚合估算，适合做规划线索而不是个人层面的确定事实。实际筛选时，把平台受众地区截图、内容语言、30 条有效评论和本地商业记录放在同一行。如果四项中只有“达人所在地”符合，就不能标记为本地匹配。\n\n例如 90 天内目标市场观看占比 62%、目标语言内容占 85%、30 条有效评论中 21 条来自本地语境，并有 2 次本地零售合作，证据明显强于个人简介中的城市名称。缺失项保留为未知，并在外联中用一个具体问题补齐。', 'TikTok Audience Insights supports exploration by interests, behaviors and demographics, while its guidance frames the data as aggregated planning insight rather than certainty about an individual. Put platform geography, content language, 30 informative comments and local commercial history on one row. If only creator location fits, do not mark local-market fit.\n\nFor example, 62% target-market views across 90 days, 85% target-language content, 21 of 30 informative comments in local context and two local retail partnerships provide stronger evidence than a city in a bio. Keep missing fields unknown and resolve them with one precise outreach question.', ['tiktokAudience']),
    table: table('本地市场证据表', 'Local-market evidence table', '使用同一平台和 90 天窗口；未知不填零。', 'Use one platform and a 90-day window; unknown is not zero.', [['证据','Evidence'],['记录','Record'],['判断','Decision']], [[['观看地区','Viewer geography'],['目标市场占比与日期','Target share and date'],['确认 / 待确认','Confirmed / pending']], [['内容语言','Content language'],['20 条近期内容','20 recent posts'],['稳定 / 偶发','Sustained / occasional']], [['评论语境','Comment context'],['30 条有效评论','30 informative comments'],['本地 / 跨境 / 未知','Local / cross-border / unknown']], [['执行条件','Feasibility'],['物流、币种、披露','Shipping, currency, disclosure'],['可执行 / 阻塞','Feasible / blocked']]]),
    tool: checklist('本地达人进入名单前复核', 'Local-creator shortlist review', '8 项直接对照，不需要打分。', 'Use eight checks without turning them into a score.', [['目标市场观看数据有日期','Target-market viewer data has a date'],['内容语言经过近期样本验证','Language verified from recent content'],['评论语境支持市场判断','Comment context supports the market'],['产品场景符合当地生活','Product use fits local life'],['报价币种与税务已确认','Currency and tax confirmed'],['物流与产品访问可执行','Shipping and product access are feasible'],['当地披露要求有负责人','Local disclosure has an owner'],['未知项已进入外联问题','Unknowns moved into outreach questions']]),
    sources: [sources.tiktokAudience, sources.tiktokDiscovery],
  },
  'competitor-creator-partnership-map': {
    deepDive: dive('用重复发布与内容任务读图谱', 'Read the map through repeat work and content jobs', 'TikTok One Top Content 让团队查看热门商业内容及观看、互动、6 秒观看等指标。这类公开资料适合识别市场正在使用的内容形式，却不能证明合作价格、排他期限或转化。图谱应把“看见的事实”和“团队推断”分栏。\n\n假设 5 个竞品在 9 个月内发布 180 条可识别合作，其中 72 条是开箱、48 条是折扣、只有 12 条回答安装或长期使用问题，那么空白比例是 6.7%。这只说明内容供给结构；下一步仍要用评论问题和自有客服数据确认用户是否真的需要这类内容。', 'TikTok One Top Content exposes popular commercial content and metrics such as views, engagement and six-second views. These public records help identify formats but do not prove price, exclusivity term or conversion. Keep observed facts separate from team inference.\n\nIf five competitors publish 180 identifiable partnerships in nine months, with 72 unboxings, 48 discounts and only 12 installation or long-term-use pieces, the latter represents 6.7% of supply. That describes content supply only; compare it with comment questions and first-party support data before calling it a real audience need.', ['tiktokTopContent']),
    table: table('竞品合作图谱字段', 'Competitor partnership-map fields', '每条记录保留原始链接和观察日期。', 'Every record keeps its source URL and observation date.', [['节点','Node'],['必填字段','Required fields'],['不要推断','Do not infer']], [[['品牌','Brand'],['市场、产品、日期','Market, product, date'],['预算','Budget']], [['达人','Creator'],['账号、平台、角色','Account, platform, role'],['独家关系','Exclusive relationship']], [['内容','Content'],['任务、形式、披露','Job, format, disclosure'],['转化','Conversion']], [['关系','Relationship'],['首次 / 重复 / 持续投放','First / repeat / active ad'],['合同期限','Contract term']]]),
    tool: checklist('竞品图谱研究清单', 'Competitor-map research checklist', '用 8 项保证图谱可复核。', 'Use eight checks to keep the map reviewable.', [['覆盖 3–5 个相关竞品','Cover three to five relevant competitors'],['观察窗口至少覆盖一个销售周期','Window covers at least one sales cycle'],['每条记录保留公开来源','Every record keeps a public source'],['主要内容任务只编码一次','Code one primary content job'],['自然发布与付费使用分开','Separate organic post from paid use'],['重复合作有新的日期证据','Repeat work has new dated evidence'],['事实与推断分栏保存','Separate facts from inference'],['空白主题用用户问题验证','Validate whitespace with user questions']]),
    sources: [sources.tiktokTopContent, sources.tiktokOne],
  },
  'detect-suspicious-creator-growth': {
    deepDive: dive('把异常检测写成可解释的复核过程', 'Make anomaly detection an explainable review process', 'FTC 的最终规则把粉丝、观看、点赞、保存、分享和评论列为可用于表达社交影响力的指标，并针对虚假指标的买卖作出规定。对品牌而言，合适动作是验证采购和使用风险，而不是根据一个突增公开指控达人。\n\n可以把 90 天拆成 13 个周窗口，分别计算粉丝净增、内容数量和同类内容观看中位数。若某周粉丝增加 35%，观看中位数仅增加 2%，同时目标市场占比变化 25 个百分点，则触发人工复核；若同周有被媒体报道的爆款并能解释地区变化，则记录反证。阈值应按账号历史设定，不能跨平台套用。', 'The FTC final rule identifies followers, views, likes, saves, shares and comments as indicators that can express social influence and regulates the sale or purchase of fake indicators. A brand should verify procurement and campaign risk rather than accuse a creator from one spike.\n\nSplit 90 days into 13 weekly windows and track net follower growth, post count and median comparable views. A week with 35% follower growth, 2% median-view growth and a 25-point geography shift can trigger review. A documented breakout covered by media may provide counterevidence. Set thresholds from account history rather than applying one rule across platforms.', ['ftcFakeIndicators']),
    table: table('异常信号复核表', 'Anomaly review table', '至少 3 个独立信号才升级，保留合理解释。', 'Escalate on at least three independent signals and preserve explanations.', [['信号','Signal'],['比较','Comparison'],['可解释事件','Explainable event']], [[['粉丝变化','Follower change'],['周环比与 13 周基线','Week over week vs 13-week baseline'],['爆款或媒体曝光','Breakout or press']], [['观看分布','View distribution'],['中位数、区间、异常点','Median, range, outlier'],['付费放大','Paid amplification']], [['评论质量','Comment quality'],['重复、语境、新账号','Repetition, context, new accounts'],['抽奖活动','Giveaway']], [['受众地区','Audience geography'],['百分点变化','Percentage-point shift'],['跨平台导流','Cross-platform traffic']]]),
    tool: checklist('异常数据人工复核顺序', 'Anomaly-data review order', '这是调查顺序，不是作弊评分。', 'This is an investigation order, not a fraud score.', [['确认截图、日期和数据窗口','Verify evidence, date and window'],['建立账号自己的 90 天基线','Build the account’s 90-day baseline'],['对齐发布、媒体与投放事件','Align content, press and paid events'],['比较同类内容中位数与区间','Compare median and range for similar posts'],['检查评论和受众地区变化','Review comments and geography shifts'],['向达人请求最小补充证据','Request minimal supporting evidence'],['同时记录解释与反证','Record explanations and counterevidence'],['设置结论有效期与复核日','Set expiry and next review date']]),
    sources: [sources.ftcFakeIndicators, sources.tiktokTopContent],
  },
  'creator-discovery-watchlist': {
    deepDive: dive('让名单规模由复核能力决定', 'Size the watchlist to review capacity', 'TikTok One 支持按关键词、国家、受众和表现等条件搜索创作者，适合补充观察名单；平台结果仍会随数据和搜索条件变化，因此每次进入名单都要保存日期与理由。\n\n若团队每月只能认真复核 40 人，而高、中、低优先级周期分别为 30、60、90 天，可维护的均衡名单约为 120 人：每月复核 20 位高优先级、12 位中优先级和 8 位低优先级。超过容量时应先删除没有明确进入理由或连续两次无新信号的记录，而不是降低复核质量。', 'TikTok One supports creator search using keywords, country, audience and performance filters, which can feed a watchlist. Results change with data and search conditions, so each entry still needs a date and reason.\n\nIf a team can review 40 creators carefully each month and uses 30-, 60- and 90-day cycles, a balanced list might hold about 120 records: 20 high-, 24 medium- and 72 low-priority creators, producing roughly 40 monthly reviews. When capacity is exceeded, remove records without a clear entry reason or new signal across two cycles rather than reducing review quality.', ['tiktokDiscovery']),
    table: table('观察名单分层', 'Watchlist tiers', '复核频率由信号强度决定，不由粉丝量决定。', 'Review cadence follows signal strength, not follower size.', [['层级','Tier'],['进入条件','Entry condition'],['复核周期','Review cycle']], [[['高','High'],['内容、受众、执行已有证据','Content, audience and feasibility evidenced'],['30 天','30 days']], [['中','Medium'],['主题相关但存在未知','Relevant with unknowns'],['60 天','60 days']], [['低','Low'],['出现一个早期信号','One early signal'],['90 天','90 days']], [['退出','Exit'],['两次无新信号或不再相关','No new signal twice or no longer relevant'],['立即归档','Archive now']]]),
    tool: checklist('观察名单最小记录', 'Minimum watchlist record', '8 个字段足够支持下一次复核。', 'Eight fields support the next review.', [['进入名单的具体理由','Specific entry reason'],['一条代表内容链接','One representative content URL'],['市场、语言和主题','Market, language and topic'],['当前证据等级','Current evidence level'],['需要观察的变化信号','Change signal to monitor'],['优先级和复核日期','Priority and review date'],['转入正式筛选的条件','Condition for formal selection'],['退出或归档条件','Exit or archive condition']]),
    sources: [sources.tiktokDiscovery],
  },
  'affiliate-creator-conversion-analysis': {
    deepDive: dive('从净收入和有效订单开始计算', 'Start with net revenue and valid orders', 'Google Analytics 的自定义 Campaign URL 指南要求一致使用 utm_source、utm_medium 和 utm_campaign 等参数。对联盟达人而言，链接、优惠码和平台订单应先汇总到同一个订单层级，再删除退款、取消、测试单和重复归因。\n\n示例：毛收入 120,000，退款 12,000，净收入为 108,000；佣金率 12% 产生 12,960 佣金，固定制作费与其他成本合计 22,000，总成本 34,960，净收入 ROAS 为 3.09。若有效订单 720，单个有效订单成本为 48.56。报告还应单列观察窗口和退款窗口，避免发布后第 3 天就把未结算订单当成最终结果。', 'Google Analytics guidance for custom campaign URLs calls for consistent parameters such as utm_source, utm_medium and utm_campaign. For affiliate creators, reconcile links, codes and platform orders at the order level before removing refunds, cancellations, tests and duplicate attribution.\n\nFor gross revenue of 120,000 and 12,000 in refunds, net revenue is 108,000. A 12% commission is 12,960; with 22,000 in fixed and other costs, total cost is 34,960 and net-revenue ROAS is 3.09. With 720 valid orders, cost per valid order is 48.56. Report the observation and refund windows so day-three orders are not treated as final.', ['gaUtm']),
    table: table('联盟转化数据对账', 'Affiliate conversion reconciliation', '订单级对账后再按达人汇总。', 'Reconcile at order level before creator totals.', [['字段','Field'],['定义','Definition'],['排除','Exclude']], [[['毛收入','Gross revenue'],['归因订单原价','Attributed order value'],['测试单','Test orders']], [['净收入','Net revenue'],['扣除退款与取消','After refunds and cancellations'],['未结算订单','Unsettled orders']], [['有效订单','Valid orders'],['满足窗口与规则','Meets window and rules'],['重复归因','Duplicate attribution']], [['总成本','Total cost'],['佣金、制作与其他成本','Commission, production and other cost'],['无关固定成本','Unrelated overhead']]]),
    tool: { kind: 'affiliate-economics', title: pair('联盟达人净收入计算器', 'Affiliate creator economics calculator'), intro: pair('用净收入、有效订单和完整成本计算可比较结果。', 'Calculate comparable results from net revenue, valid orders and full cost.'), inputs: [{ key: 'grossRevenue', label: pair('毛收入', 'Gross revenue'), value: 120000, min: 0, step: 100 }, { key: 'refunds', label: pair('退款与取消', 'Refunds and cancellations'), value: 12000, min: 0, step: 100 }, { key: 'commissionRate', label: pair('佣金率 %', 'Commission rate %'), value: 12, min: 0, max: 100, step: 0.1 }, { key: 'fixedCost', label: pair('固定制作费', 'Fixed creator fee'), value: 18000, min: 0, step: 100 }, { key: 'otherCost', label: pair('产品、物流与工具成本', 'Product, logistics and tools'), value: 4000, min: 0, step: 100 }, { key: 'validOrders', label: pair('有效订单数', 'Valid orders'), value: 720, min: 0, step: 1 }] },
    sources: [sources.gaUtm],
  },
  'creator-campaign-incrementality': {
    deepDive: dive('先写实验单位，再讨论提升', 'Define the experimental unit before lift', 'Google Ads 将实验用于测试 Campaign 设置变化，并建议一次只测试一个变量；Conversion Lift 则通过处理组和控制组的转化差异估算增量。达人营销可以借用这一结构，但实验单位可能是地区、人群或时间段，必须在发布前确定，不能发布后挑出表现最好的对照。\n\n假设处理组 50,000 人产生 1,400 次转化，转化率 2.8%；控制组 50,000 人产生 1,100 次，转化率 2.2%。绝对提升是 0.6 个百分点，相对提升约 27.3%，情景增量转化为 300。该简单计算不代表统计显著，样本污染、并行促销和跨组曝光仍需单独检查。', 'Google Ads experiments test campaign changes and recommend one variable at a time, while Conversion Lift uses the conversion difference between treatment and control to estimate incrementality. Creator campaigns can borrow the structure, but the experimental unit—market, audience or time period—must be fixed before launch rather than selected after results.\n\nIf 50,000 people in treatment produce 1,400 conversions, the rate is 2.8%; 1,100 conversions among 50,000 controls produce 2.2%. Absolute lift is 0.6 percentage points, relative lift is about 27.3% and scenario incremental conversions are 300. This simple calculation does not establish statistical significance; contamination, parallel promotion and cross-group exposure still need review.', ['googleExperiments', 'googleLift']),
    table: table('增量测试设计记录', 'Incrementality test design record', '发布前冻结设计和排除规则。', 'Freeze design and exclusions before launch.', [['项目','Item'],['发布前记录','Pre-launch record'],['发布后检查','Post-launch check']], [[['实验单位','Experimental unit'],['地区 / 人群 / 时间','Market / audience / time'],['是否串组','Contamination']], [['主要指标','Primary metric'],['唯一转化定义','One conversion definition'],['数据完整性','Data completeness']], [['观察窗口','Observation window'],['开始、结束、延迟','Start, end, lag'],['并行活动','Parallel activity']], [['停止规则','Stop rule'],['样本或时间门槛','Sample or time threshold'],['是否提前查看','Early peeking']]]),
    tool: { kind: 'incrementality', title: pair('处理组与控制组增量计算器', 'Treatment-control lift calculator'), intro: pair('计算绝对提升、相对提升与情景增量；不代替显著性检验。', 'Calculate absolute lift, relative lift and scenario incrementality; this is not a significance test.'), inputs: [{ key: 'treatmentSize', label: pair('处理组人数', 'Treatment population'), value: 50000, min: 1, step: 100 }, { key: 'treatmentConversions', label: pair('处理组转化', 'Treatment conversions'), value: 1400, min: 0, step: 1 }, { key: 'controlSize', label: pair('控制组人数', 'Control population'), value: 50000, min: 1, step: 100 }, { key: 'controlConversions', label: pair('控制组转化', 'Control conversions'), value: 1100, min: 0, step: 1 }, { key: 'campaignCost', label: pair('Campaign 总成本', 'Total campaign cost'), value: 90000, min: 0, step: 100 }] },
    sources: [sources.googleExperiments, sources.googleLift],
  },
  'analyze-creator-comment-quality': {
    deepDive: dive('抽样评论时同时保留分母和语境', 'Keep the denominator and context in comment sampling', 'FTC 的虚假社交指标规则提醒品牌，评论也可能被用于表达影响力，因此不能把评论数量直接当成受众兴趣。建议从同类内容中抽取至少 100 条非置顶评论，记录问题、经验、购买意图、异议、低信息互动、重复文本和疑似无关流量。\n\n例如 120 条样本中有 28 条具体问题、22 条真实经验、14 条购买意图、18 条异议、30 条低信息互动、8 条重复或无关文本。高信息评论为 64 条，占 53.3%；这个比例只能描述本次样本，不能推断全部粉丝。最好由第二位审核者复查 20 条，比较分类一致性。', 'The FTC rule on fake social indicators reminds brands that comments can be used to express influence, so raw comment count is not audience interest. Sample at least 100 non-pinned comments across comparable posts and code questions, experiences, purchase intent, objections, low-information reactions, repetitive text and irrelevant traffic.\n\nIn a sample of 120, there may be 28 specific questions, 22 experiences, 14 purchase-intent comments, 18 objections, 30 low-information reactions and eight repetitive or irrelevant comments. The 64 high-information comments represent 53.3% of the sample only, not all followers. Have a second reviewer recode 20 comments and compare agreement.', ['ftcFakeIndicators']),
    table: table('评论样本编码表', 'Comment-sample coding table', '每条只标一个主要意图，保留原文链接。', 'Assign one primary intent and keep the source URL.', [['类别','Category'],['判定线索','Signal'],['可支持的判断','Supported inference']], [[['问题','Question'],['请求具体信息','Requests specific information'],['信息需求','Information need']], [['经验','Experience'],['描述使用或比较','Describes use or comparison'],['场景相关性','Use-case relevance']], [['购买意图','Purchase intent'],['价格、渠道、库存','Price, retailer, availability'],['行动兴趣','Action interest']], [['低信息 / 无关','Low-information / irrelevant'],['表情、重复、跑题','Emoji, repetition, off-topic'],['不支持质量结论','No quality conclusion']]]),
    tool: checklist('评论质量抽样流程', 'Comment-quality sampling process', '8 步建立可复核的评论样本。', 'Eight steps create a reviewable comment sample.', [['选取 5–10 条同类内容','Choose five to ten comparable posts'],['排除置顶与创作者自评','Exclude pinned and creator comments'],['保留至少 100 条随机样本','Keep at least 100 random comments'],['每条只编码一个主要意图','Code one primary intent per comment'],['记录语言、日期与内容链接','Record language, date and post URL'],['分开低信息与可疑重复','Separate low information from suspicious repetition'],['由第二人复查 20 条','Second reviewer recodes 20 comments'],['报告样本数和限制','Report sample size and limitations']]),
    sources: [sources.ftcFakeIndicators],
  },
  'scale-creator-outreach-without-spam': {
    deepDive: dive('用小批次验证名单与信息质量', 'Validate list and message quality in small batches', '规模化外联的安全阀不是发送速度，而是批次门槛。先发送 20 封，记录送达、有效回复、拒绝、停止请求、信息错误和人工修改。如果 20 封中 3 封邮箱错误、4 封引用了不相关内容，数据问题率已经是 35%，应暂停并修正名单。\n\n下一批只在阻断错误为 0、停止请求已同步、有效回复中没有重复触达投诉时扩大，例如从 20 增至 50，再到 100。NIST AI RMF 强调持续测量和管理风险；QuickKOL 中为每条联系保存名单版本、模板版本、个性化证据和发送人，使团队能够停止某一批，而不用关闭全部外联。', 'The safety control for scaled outreach is a batch gate, not send speed. Start with 20 messages and record delivery, useful replies, declines, stop requests, data errors and manual edits. If three addresses are wrong and four messages reference irrelevant content, the data issue rate is already 35%; pause and fix the list.\n\nExpand from 20 to 50 and then 100 only when blocking errors are zero, stop requests are synchronized and useful replies show no duplicate-contact complaints. NIST AI RMF emphasizes continuous risk measurement and management. Save list version, template version, personalization evidence and sender for each contact so one batch can be stopped without shutting down all outreach.', ['nistAiRmf']),
    table: table('外联批次质量门槛', 'Outreach batch quality gates', '门槛应在发送前写明。', 'Write thresholds before sending.', [['指标','Metric'],['示例门槛','Example gate'],['超出动作','Action if exceeded']], [[['阻断事实错误','Blocking factual error'],['0','0'],['立即暂停','Pause immediately']], [['退信率','Bounce rate'],['< 3%','< 3%'],['验证地址来源','Verify address source']], [['停止请求','Stop request'],['100% 当日同步','100% same-day sync'],['冻结后续发送','Suppress future sends']], [['人工改写率','Manual rewrite rate'],['< 20%','< 20%'],['修正数据或模板','Fix data or template']]]),
    tool: checklist('外联批次发送前检查', 'Pre-send batch review', '短清单直接用于批次审批。', 'Use this concise list for batch approval.', [['名单来源与提取日期已记录','List source and date recorded'],['邮箱、代理关系和时区已验证','Email, agency and time zone verified'],['每封引用一条真实内容证据','Each message cites real content evidence'],['范围、预算与下一步一致','Scope, budget and next step align'],['重复联系和停止请求已排除','Duplicates and stop requests removed'],['批次上限和暂停门槛已设置','Batch cap and pause threshold set'],['人工审核样本已通过','Human review sample passed'],['回复由明确负责人处理','Replies have a named owner']]),
    sources: [sources.nistAiRmf],
  },
  'creator-agency-or-direct-outreach': {
    deepDive: dive('先确认谁能决定哪一件事', 'Confirm who can decide each issue', '平台档案、个人邮箱、经纪公司和管理团队可能同时存在。最有效的做法不是多头发送，而是建立责任表：达人确认创作适配与档期，代理处理报价和合同，品牌负责人批准预算，法务确认权益。TikTok One 的合作流程区分邀请、申请、项目沟通和广告账户操作，也说明平台中的账号动作不等于线下商业授权。\n\n若 24 小时内收到两个不同联系人回复，先暂停后续自动跟进，在同一封邮件中确认主联系人和抄送规则。记录“谁说了什么、何时生效”，避免达人已经拒绝而代理仍在推进，或同一报价被两个线程修改。', 'A platform profile, personal email, talent agency and management team may all coexist. Avoid parallel messages by mapping decision rights: the creator confirms creative fit and availability, the agent handles quote and contract, the brand owner approves budget and legal confirms rights. TikTok One separates invitations, applications, project communication and ad-account actions, showing that a platform action is not the same as offline commercial authority.\n\nIf two contacts reply within 24 hours, pause automated follow-ups and confirm the primary contact and copy rules in one thread. Record who said what and when it became effective so a creator decline is not contradicted by an agent or one quote changed in two threads.', ['tiktokOne']),
    table: table('达人合作责任表', 'Creator partnership responsibility table', '一个议题只设一个最终确认人。', 'Assign one final confirmer per issue.', [['议题','Issue'],['通常确认人','Typical confirmer'],['证据','Evidence']], [[['内容适配','Creative fit'],['达人','Creator'],['书面确认','Written confirmation']], [['报价与合同','Quote and contract'],['代理 / 达人','Agent / creator'],['当前版本','Current version']], [['档期与交付','Timing and delivery'],['项目联系人','Project contact'],['里程碑日期','Milestone dates']], [['权益与广告权限','Rights and ad access'],['授权方与品牌','Grantor and brand'],['合同与平台状态','Contract and platform status']]]),
    tool: checklist('确定直接联系或代理联系', 'Decide direct or agency contact', '8 项确认沟通路径。', 'Eight checks establish the communication path.', [['主页上的商务联系人已核对','Published business contact verified'],['代理关系通过公开来源确认','Agency relationship verified publicly'],['只发送一个初始线程','One initial thread only'],['主联系人与抄送规则明确','Primary contact and copy rules clear'],['报价、创作和法务责任分开','Commercial, creative and legal roles separated'],['停止请求同步到全部联系人','Stop request synced to all contacts'],['当前范围只有一个版本','One current scope version'],['所有决定回写 QuickKOL','All decisions saved in QuickKOL']]),
    sources: [sources.tiktokOne],
  },
  'reengage-past-creators': {
    deepDive: dive('让再次联系有新的合作理由', 'Give re-engagement a new reason', '过去合作成功不代表下一次仍然适合。重新联系前比较上次 Campaign 的内容任务、受众、档期、报价、反馈速度、权益状态和付款完成情况，再检查近 90 天内容是否仍与新 Brief 相关。TikTok One 等平台搜索可以补充近期信号，但不能覆盖已确认的合作事实。\n\n可以按 5 项建立复用记录：上次交付完整度、数据可用性、受众匹配、合作体验和新任务匹配，每项只写事实，不做永久总分。例如上次 4 项交付全部准时、目标市场观看 58%、两轮审核内通过，但新 Campaign 需要直播而达人近一年没有直播记录，则应把直播能力列为未知，而不是依靠历史关系直接入选。', 'A successful previous campaign does not guarantee current fit. Before re-contacting, compare the last campaign’s content job, audience, timing, quote, response speed, rights status and payment completion, then inspect 90 days of content for the new brief. TikTok One and similar discovery tools can add recent signals but should not overwrite confirmed partnership facts.\n\nMaintain five evidence fields: delivery completeness, data availability, audience fit, working experience and new-job fit. Avoid permanent scores. If all four deliverables were on time, target-market viewing reached 58% and review finished in two rounds, but the new campaign requires live content and the creator has no live record in a year, mark live capability unknown rather than selecting on relationship alone.', ['tiktokDiscovery']),
    table: table('再次合作判断表', 'Re-engagement decision table', '历史表现与当前适配分开判断。', 'Separate historical performance from current fit.', [['维度','Dimension'],['历史事实','Historical fact'],['本次确认','Current confirmation']], [[['交付','Delivery'],['准时率与返工','On-time rate and rework'],['新格式能力','New-format capability']], [['受众','Audience'],['历史市场数据','Historical market data'],['近期受众窗口','Recent audience window']], [['商务','Commercial'],['报价与付款','Quote and payment'],['当前费率与档期','Current rate and availability']], [['权益','Rights'],['旧权限到期','Prior expiry'],['新用途与期限','New use and term']]]),
    tool: checklist('联系历史达人前复核', 'Before re-contacting a past creator', '8 项确认这次联系确实有价值。', 'Eight checks make the new contact useful.', [['上次付款和承诺已完成','Prior payment and commitments completed'],['旧使用权与广告权限已核对','Old rights and ad access checked'],['新 Brief 与历史任务有区别','New brief differs from prior job'],['近期内容与受众重新查看','Recent content and audience reviewed'],['本次联系有明确新理由','Contact has a clear new reason'],['不引用过期报价或档期','No stale quote or availability'],['历史问题已有改进动作','Past issues have mitigation'],['下一步和回复截止日清楚','Next step and reply date clear']]),
    sources: [sources.tiktokDiscovery],
  },
  'evaluate-creator-rate-cards': {
    deepDive: dive('把报价统一成范围，而不是一个总价', 'Normalize quote scope instead of comparing totals', '两份报价只有在交付、平台、制作、修改、自然使用、付费使用、排他、原始素材、期限、税务和付款条件一致时才能直接比较。Meta 将 branded content 与 partnership ads 作为相关但不同的商业功能；是否只发布内容、是否授权广告放大，会改变实际范围。\n\n示例：报价 A 为 18,000，含 1 条视频和 30 天自然使用；报价 B 为 25,000，含 2 条视频、3 个月付费使用和原始素材。把每个附加项拆开后，B 不一定更贵。标准化只让范围可见，不用于宣称市场“合理价”。最终价格仍由双方谈判和价值判断决定。', 'Two quotes are comparable only when deliverables, platform, production, revisions, organic use, paid use, exclusivity, raw files, term, tax and payment conditions align. Meta treats branded content and partnership ads as related but distinct commercial capabilities; posting only and paid amplification are different scopes.\n\nQuote A may be 18,000 for one video and 30 days of organic use; quote B may be 25,000 for two videos, three months of paid use and raw files. Once add-ons are separated, B is not automatically more expensive. Normalization reveals scope and does not declare a “market rate.” Final price remains a negotiated value decision.', ['metaBranded', 'metaPartnership']),
    table: table('报价标准化项目', 'Quote normalization fields', '所有金额保留币种、税务和有效期。', 'Keep currency, tax treatment and validity date.', [['范围项','Scope item'],['单位','Unit'],['确认问题','Question']], [[['内容制作','Production'],['件 / 格式','Asset / format'],['包含几轮修改','Revision rounds']], [['自然发布','Organic posting'],['平台 / 期限','Platform / term'],['是否保留上线','Required live period']], [['付费使用','Paid use'],['月 / 市场','Month / market'],['账户与广告形式','Account and ad type']], [['排他与素材','Exclusivity and files'],['品类 / 文件','Category / file'],['范围与交付格式','Scope and delivery format']]]),
    tool: { kind: 'quote-normalize', title: pair('达人报价范围标准化计算器', 'Creator quote normalization calculator'), intro: pair('拆分基础费、交付、权益与附加项，得到可比较情景。', 'Separate base fee, deliverables, rights and add-ons into a comparable scenario.'), inputs: [{ key: 'baseFee', label: pair('基础制作与发布费', 'Base production and posting fee'), value: 18000, min: 0, step: 100 }, { key: 'assets', label: pair('包含内容数量', 'Included assets'), value: 2, min: 1, step: 1 }, { key: 'rightsMonths', label: pair('付费使用月数', 'Paid-use months'), value: 3, min: 0, step: 1 }, { key: 'monthlyRights', label: pair('每月权益费', 'Rights fee per month'), value: 2500, min: 0, step: 100 }, { key: 'addOns', label: pair('原始素材、排他等附加项', 'Raw files, exclusivity and add-ons'), value: 4000, min: 0, step: 100 }, { key: 'qualifiedViews', label: pair('预计目标市场观看', 'Estimated target-market views'), value: 80000, min: 0, step: 1000 }] },
    sources: [sources.metaBranded, sources.metaPartnership],
  },
  'creator-usage-rights-renewal': {
    deepDive: dive('把到期管理拆成内容、渠道和权限', 'Separate asset, channel and permission expiry', '一条内容可能同时存在品牌自然转发、付费广告、创作者账号授权、剪辑版本和不同市场的期限。Meta 的 partnership ads 依赖创作者与品牌之间的广告权限，因此合同结束和平台权限结束都要核对，不能只在日历里写一个总到期日。\n\n建议在到期前 45 天启动复核：列出仍在投放的素材、过去 30 天花费与结果、剩余媒体计划、原始授权范围和更新报价。若 6 条素材中只有 2 条仍贡献 82% 的有效转化，可以只续 2 条；更新后的开始日、结束日、市场、账户和允许修改范围都要重新书面确认。', 'One asset can have different terms for organic reposting, paid ads, creator-handle authorization, edits and markets. Meta partnership ads depend on permissions between creator and brand, so contract expiry and platform permission expiry both require review rather than one calendar date.\n\nStart review 45 days before expiry. List active assets, 30-day spend and outcomes, remaining media plan, original grant and renewal quote. If two of six assets contribute 82% of qualified conversions, renew only those two. Confirm new start date, end date, market, account and permitted edits in writing.', ['metaPartnership']),
    table: table('权益续期记录', 'Rights renewal record', '每个素材单独记录，不用一个总到期日覆盖全部。', 'Track every asset separately rather than one global expiry.', [['字段','Field'],['原授权','Original grant'],['续期决定','Renewal decision']], [[['素材 ID','Asset ID'],['文件与版本','File and version'],['续 / 停 / 替换','Renew / stop / replace']], [['渠道与账户','Channel and account'],['自然 / 付费 / 达人账号','Organic / paid / creator handle'],['保持或缩小','Keep or narrow']], [['市场与期限','Market and term'],['开始与结束','Start and end'],['新日期','New dates']], [['修改权限','Editing right'],['字幕、裁切、配音','Captions, crop, dubbing'],['书面更新','Written update']]]),
    tool: checklist('权益到期前 45 天复核', '45-day rights-expiry review', '8 项决定续期、缩小或停止。', 'Eight checks support renew, narrow or stop.', [['列出全部仍在使用的素材','List every asset still in use'],['核对合同与平台权限日期','Check contract and platform permission dates'],['汇总过去 30 天花费与结果','Summarize 30-day spend and outcomes'],['确认剩余媒体计划和市场','Confirm remaining media plan and markets'],['只续仍有明确用途的素材','Renew only assets with a defined use'],['重新确认剪辑与配音权限','Reconfirm editing and dubbing rights'],['设置下架和权限撤销负责人','Assign takedown and revocation owners'],['新条款回写素材记录','Write new terms to asset records']]),
    sources: [sources.metaPartnership, sources.metaBranded],
  },
  'price-creator-exclusivity': {
    deepDive: dive('用被限制的机会解释排他成本', 'Explain exclusivity through constrained opportunity', '排他不是一个固定加价百分比，而是对创作者未来商业机会的限制。先定义品类、竞争品牌、市场、平台、期限、内容类型和冷却期，再估算在该窗口内可能被阻止的合作。范围越宽，品牌承担的成本和合同歧义越高。\n\n例如创作者每年平均完成 18 个付费合作，目标品类约占 20%，平均净价值 12,000。6 个月全品类排他在简单情景下可能影响 18 ÷ 12 × 6 × 20% = 1.8 个机会，机会价值约 21,600。这个数字只用于谈判范围，不是应付价格；实际概率、季节性和替代品类还要双方确认。品牌还应提出一个更窄的对照方案，例如只限制 3 个列名竞品、单一平台和发布前后 14 天，让双方看到减少范围会释放多少机会。', 'Exclusivity is not a fixed percentage markup; it constrains future commercial opportunity. Define category, named competitors, market, platform, term, content type and cooldown, then estimate deals potentially blocked. A broader scope increases both cost and contractual ambiguity.\n\nIf a creator completes 18 paid partnerships per year, 20% relate to the target category and average net value is 12,000, six months of category-wide exclusivity may affect 18 ÷ 12 × 6 × 20% = 1.8 opportunities, worth about 21,600 in a simple scenario. This frames negotiation rather than setting a price; probability, seasonality and substitute categories still need agreement. Add a narrower comparison—three named competitors, one platform and 14 days around publication—so both sides can see how reduced scope releases opportunity.', ['metaBranded']),
    table: table('排他范围定义', 'Exclusivity scope definition', '不能只写“竞品排他”。', 'Do not write only “competitor exclusivity.”', [['维度','Dimension'],['窄范围示例','Narrow example'],['宽范围风险','Broad-scope risk']], [[['品牌','Brands'],['列名 3 个直接竞品','Three named competitors'],['包含全部相邻品牌','All adjacent brands']], [['产品','Products'],['同一子品类','Same subcategory'],['整个行业','Whole industry']], [['渠道','Channel'],['一项平台赞助内容','Sponsored content on one platform'],['所有公开内容','All public content']], [['时间','Time'],['发布前后 14 天','14 days around publication'],['6–12 个月含冷却期','6–12 months plus cooldown']]]),
    tool: { kind: 'exclusivity-cost', title: pair('排他机会成本情景计算器', 'Exclusivity opportunity-cost calculator'), intro: pair('用历史合作频率、范围比例和期限估算被限制机会。', 'Estimate constrained opportunities from historic deal frequency, scope and term.'), inputs: [{ key: 'months', label: pair('排他月数', 'Exclusivity months'), value: 6, min: 0, step: 1 }, { key: 'annualDeals', label: pair('每年平均付费合作数', 'Average paid deals per year'), value: 18, min: 0, step: 1 }, { key: 'scopePercent', label: pair('可能受限合作占比 %', 'Share of deals potentially constrained %'), value: 20, min: 0, max: 100, step: 1 }, { key: 'averageValue', label: pair('每次合作平均净价值', 'Average net value per deal'), value: 12000, min: 0, step: 100 }] },
    sources: [sources.metaBranded],
  },
  'partnership-ads-permission-checklist': {
    deepDive: dive('合同授权和平台权限必须同时成立', 'Contract authority and platform permission must both exist', 'Meta 的品牌内容与 partnership ads 体系要求品牌和创作者使用相应披露与权限功能。品牌在平台中能选择素材，并不自动意味着合同允许所有市场、期限、剪辑或广告账户使用；合同允许投放，也不保证平台权限仍有效。\n\n上线前做双重核对：合同层记录素材 ID、广告形式、账户、市场、开始与结束、修改权限；平台层确认身份、合作标签、授权状态和预览。上线后 24 小时保存首个投放截图，到期日执行停止、权限撤销和证据归档，避免素材在合同结束后继续消耗预算。', 'Meta’s branded-content and partnership-ads systems require appropriate disclosures and permissions. Platform selection of an asset does not prove the contract permits every market, term, edit or ad account; contractual rights do not guarantee the platform permission remains active.\n\nBefore launch, run two checks. Contract records cover asset ID, ad type, account, market, start and end dates and editing rights; platform records cover identity, partnership label, authorization and preview. Save first-delivery evidence within 24 hours, then stop delivery, revoke permission and archive evidence at expiry.', ['metaBranded', 'metaPartnership']),
    table: table('Partnership Ads 上线矩阵', 'Partnership ads launch matrix', '合同、平台与投放三列都通过才上线。', 'Launch only when contract, platform and delivery all pass.', [['检查层','Review layer'],['必须确认','Must confirm'],['负责人','Owner']], [[['合同','Contract'],['素材、市场、期限、修改','Asset, market, term, edits'],['法务 / 商务','Legal / commercial']], [['平台','Platform'],['身份、标签、权限','Identity, label, permission'],['达人 / 运营','Creator / operations']], [['广告账户','Ad account'],['账户、目标、预算','Account, objective, budget'],['投放','Media']], [['到期','Expiry'],['停止、撤权、归档','Stop, revoke, archive'],['运营','Operations']]]),
    tool: checklist('Partnership Ads 上线前 10 项', 'Ten checks before partnership ads launch', '这是一次性上线核对，不需要下载。', 'Use this one-time launch reference without a download.', [['内容和账号身份一致','Asset and account identity align'],['品牌合作披露已显示','Branded-content disclosure is visible'],['合同明确允许付费投放','Contract permits paid amplification'],['广告账户和市场在范围内','Ad account and markets are in scope'],['开始日与结束日已设置','Start and end dates are set'],['裁切、字幕和配音权限明确','Crop, caption and dubbing rights are clear'],['平台授权状态已验证','Platform permission is verified'],['预览中的文案与链接已检查','Preview copy and links are checked'],['到期停止与撤权有负责人','Expiry stop and revocation have owners'],['上线证据将于 24 小时内保存','Launch evidence will be saved in 24 hours']]),
    sources: [sources.metaBranded, sources.metaPartnership],
  },
  'multilingual-creator-campaign': {
    deepDive: dive('把语言版本当成独立交付物管理', 'Manage each language version as a distinct deliverable', 'YouTube 的多语言音轨功能允许一个视频附加多种语言音轨，自动配音也可能生成其他语言版本；官方同时提供发布前复核配音的选项。这意味着品牌不能只批准原始脚本，还要明确哪些语言由达人录制、哪些由专业配音、哪些使用自动生成，以及谁批准产品名、声明和披露。\n\n例如 1 条主视频覆盖 4 种语言，会形成至少 4 个脚本、4 个音轨、4 套字幕和 4 次质量确认。抽样可要求每个版本由 1 位母语审核者检查 10 个关键术语，并对开场、价格、功效、行动提示和披露逐项通过。翻译流畅不等于法律和产品事实准确。', 'YouTube multi-language audio can attach multiple audio tracks to one video, while automatic dubbing can generate other-language versions; its controls can allow review before publication. The brand therefore needs approval rules beyond the source script: which languages are creator-recorded, professionally dubbed or automated, and who approves product names, claims and disclosures.\n\nOne video in four languages creates at least four scripts, four audio tracks, four subtitle sets and four quality checks. Require a native reviewer for each version to check ten critical terms plus the opening, price, claims, call to action and disclosure. Fluent translation is not proof of legal or product accuracy.', ['youtubeMultilanguage', 'youtubeDubbing']),
    table: table('多语言交付矩阵', 'Multilingual delivery matrix', '每个语言版本都有独立状态与负责人。', 'Every language version has its own status and owner.', [['版本','Version'],['制作方式','Production method'],['审批','Approval']], [[['原始语言','Source language'],['达人原声','Creator original'],['品牌与法务','Brand and legal']], [['翻译脚本','Translated script'],['人工翻译 / 编辑','Human translation / edit'],['母语审核','Native review']], [['音轨','Audio track'],['达人 / 配音 / 自动','Creator / voice / automatic'],['产品事实复核','Product-fact review']], [['字幕与披露','Captions and disclosure'],['平台文件','Platform file'],['上线预览','Publication preview']]]),
    tool: checklist('多语言发布前检查', 'Multilingual pre-publication review', '10 项覆盖内容、产品和披露。', 'Ten checks cover content, product and disclosure.', [['每个语言版本有明确负责人','Every language version has an owner'],['产品名和专有词一致','Product names and terms are consistent'],['价格、币种和单位本地化','Price, currency and units are localized'],['功效与禁用声明已复核','Claims and prohibited wording reviewed'],['口语表达由母语者检查','Natural speech checked by a native reviewer'],['字幕与音轨时间对齐','Captions align with audio'],['披露在目标语言中清楚','Disclosure is clear in target language'],['画面文字同步修改','On-screen text is localized'],['平台自动配音已预览','Automatic dubbing is previewed'],['最终文件与批准版本一致','Final files match approved versions']]),
    sources: [sources.youtubeMultilanguage, sources.youtubeDubbing],
  },
  'creator-live-campaign-runbook': {
    deepDive: dive('直播要同时记录并发、留存和行动结果', 'Track concurrency, retention and actions together', 'YouTube 的直播分析包含同时观看人数、聊天消息和关键互动等直播特有信息。品牌不能只报峰值在线：峰值可能来自开场抽奖，却没有带来产品理解或行动。把直播时间线与产品首次出现、演示、优惠、问答和技术故障对齐。\n\n示例：60 分钟直播峰值并发 8,400，平均并发 4,900，总观看 72,000，链接点击 3,600，有效订单 420。点击率应以适合的观看分母注明，订单率 11.7% 则以点击为分母。若第 22 分钟音频中断 4 分钟，该区间不能直接拿来评价达人讲解能力。', 'YouTube live analytics includes concurrent viewers, chat messages and other live-specific signals. Do not report peak concurrency alone: a giveaway may produce a peak without product understanding or action. Align the stream timeline with first product appearance, demonstration, offer, Q&A and technical failures.\n\nFor a 60-minute live stream with 8,400 peak and 4,900 average concurrent viewers, 72,000 total views, 3,600 link clicks and 420 valid orders, label the correct viewer denominator for click rate; order rate by clicks is 11.7%. If audio fails for four minutes at minute 22, do not treat that interval as creator explanation performance.', ['youtubeLive']),
    table: table('直播运营时间线', 'Live campaign timeline', '负责人和备用方案在开播前确定。', 'Assign owners and backups before going live.', [['阶段','Stage'],['关键动作','Key action'],['记录','Record']], [[['T-7 天','T-7 days'],['脚本、产品、披露与技术彩排','Script, product, disclosure, technical rehearsal'],['问题与负责人','Issues and owners']], [['T-30 分钟','T-30 minutes'],['权限、链接、库存和备用网络','Access, links, inventory and backup network'],['通过 / 阻塞','Pass / blocked']], [['直播中','During live'],['时间线、故障、问答与行动提示','Timeline, incidents, Q&A and calls to action'],['时间戳','Timestamps']], [['T+24 小时','T+24 hours'],['数据快照、订单对账、素材保存','Snapshot, order reconciliation, asset archive'],['最终状态','Final status']]]),
    tool: checklist('直播开播前 12 项', 'Twelve checks before going live', '短运行手册用于开播会议。', 'Use this concise runbook in the pre-live meeting.', [['账号与直播权限已验证','Account and live access verified'],['主设备、备用设备和网络可用','Primary and backup equipment work'],['产品、价格和库存同步','Product, price and inventory align'],['链接、优惠码与 UTM 已测试','Links, codes and UTM are tested'],['脚本节点和演示顺序明确','Script beats and demo order are clear'],['广告披露将在开场和关键段出现','Disclosure appears at opening and key moments'],['禁用声明和升级路径明确','Prohibited claims and escalation path are clear'],['主持、评论管理和技术负责人到位','Host, moderation and technical owners are present'],['突发问题与停播条件已定义','Incident and stop conditions are defined'],['录制、剪辑与使用权已确认','Recording, edits and rights are confirmed'],['数据快照时间已安排','Analytics snapshot timing is scheduled'],['复盘会议与负责人已确定','Review meeting and owner are set']]),
    sources: [sources.youtubeLive, sources.gaUtm],
  },
  'manage-creator-brief-changes': {
    deepDive: dive('任何变更都要显示时间、成本和依赖', 'Make time, cost and dependencies visible for every change', 'Brief 变更最常见的问题不是修改本身，而是口头要求进入制作后没有更新范围。用一张变更单记录提出人、旧要求、新要求、原因、受影响交付、已完成工作、额外成本、延迟天数和批准人。NIST AI RMF 强调治理与责任；无论变更由人还是 AI 建议，未批准前，原版本仍是执行依据。\n\n例如视频完成 70% 后新增 2 个产品场景，现有制作费 20,000，预计 35% 工作需要返工，返工成本情景为 7,000；新增场景每个 3,000，再加入 10% 不确定性预备，总影响约 14,300。计算不是自动接受报价，而是让品牌在删减、延期或增资之间做明确选择。', 'The main problem with brief changes is not change itself but verbal requests entering production without a scope update. Use one change record for requester, old requirement, new requirement, reason, affected deliverables, completed work, added cost, delay and approver. NIST AI RMF emphasizes governance and accountability; whether a change is proposed by a person or AI, the prior version remains the baseline until approval.\n\nIf production is 70% complete and two product scenes are added, with 20,000 in current production cost and 35% estimated rework, rework is 7,000. Two scenes at 3,000 each plus 10% uncertainty produces about 14,300 in total impact. The calculator does not accept a quote; it makes the choice among removing scope, delaying or adding budget explicit.', ['nistAiRmf']),
    table: table('Brief 变更单', 'Brief change record', '每次变更生成新版本，不覆盖原文。', 'Create a new version for every change.', [['字段','Field'],['必须回答','Must answer'],['负责人','Owner']], [[['变化','Change'],['旧要求与新要求','Old and new requirement'],['提出人','Requester']], [['影响','Impact'],['交付、依赖、已完成工作','Deliverables, dependency, completed work'],['制作负责人','Production owner']], [['选择','Decision'],['删减 / 延期 / 增资 / 拒绝','Reduce / delay / fund / decline'],['预算负责人','Budget owner']], [['批准','Approval'],['版本、日期、生效时间','Version, date, effective time'],['双方确认','Both parties']]]),
    tool: { kind: 'scope-change', title: pair('Brief 变更影响计算器', 'Brief change impact calculator'), intro: pair('估算返工、新增交付、预备金和延迟，支持范围决策。', 'Estimate rework, added deliverables, reserve and delay for a scope decision.'), inputs: [{ key: 'completedCost', label: pair('当前已投入制作成本', 'Current production cost'), value: 20000, min: 0, step: 100 }, { key: 'reworkPercent', label: pair('预计需要返工 %', 'Estimated rework %'), value: 35, min: 0, max: 100, step: 1 }, { key: 'addedDeliverables', label: pair('新增交付数量', 'Added deliverables'), value: 2, min: 0, step: 1 }, { key: 'costPerDeliverable', label: pair('每个新增交付成本', 'Cost per added deliverable'), value: 3000, min: 0, step: 100 }, { key: 'contingency', label: pair('不确定性预备 %', 'Uncertainty reserve %'), value: 10, min: 0, max: 100, step: 1 }, { key: 'delayDays', label: pair('预计延迟天数', 'Estimated delay days'), value: 4, min: 0, step: 1 }] },
    sources: [sources.nistAiRmf],
  },
  'ai-creator-taxonomy': {
    deepDive: dive('分类体系需要版本、定义和反例', 'A taxonomy needs versions, definitions and counterexamples', 'AI 分类最容易把一个账号永久固定在一个标签里。更稳妥的做法是把内容主题、内容形式、受众问题、商业任务和风险状态分成不同字段，每个字段保存定义、正例、反例、证据窗口和置信度。NIST AI RMF 的 Govern、Map、Measure、Manage 结构强调持续描述使用场景、测量和管理风险；分类体系也应有负责人和复核周期。\n\n从 200 个账号中抽取 40 个双人标注样本。如果“教程型”有 32 个一致、8 个不一致，简单一致率为 80%。先检查定义和边界样本，再扩展自动分类。不要用总粉丝量补足缺失主题证据，也不要让模型生成的标签覆盖人工确认字段。', 'AI classification can freeze a creator into one permanent label. Separate content topic, format, audience problem, commercial job and risk status. Give every field a definition, positive example, counterexample, evidence window and confidence. NIST AI RMF’s Govern, Map, Measure and Manage structure emphasizes use context, measurement and ongoing risk management; the taxonomy likewise needs an owner and review cycle.\n\nDouble-label a sample of 40 from 200 accounts. If reviewers agree on 32 “tutorial” labels and disagree on eight, simple agreement is 80%. Review definitions and edge cases before scaling automation. Do not substitute follower count for missing topic evidence or let generated labels overwrite human-confirmed fields.', ['nistAiRmf']),
    table: table('达人分类体系层级', 'Creator taxonomy layers', '每一层只回答一种问题。', 'Each layer answers one type of question.', [['层级','Layer'],['示例','Example'],['证据窗口','Evidence window']], [[['主题','Topic'],['护肤、效率、旅行','Skincare, productivity, travel'],['20 条近期内容','20 recent posts']], [['形式','Format'],['教程、直播、评测','Tutorial, live, review'],['同类样本','Comparable sample']], [['受众问题','Audience problem'],['如何选择 / 如何使用','How to choose / use'],['评论与搜索','Comments and search']], [['商业任务','Commercial job'],['教育、转化、素材','Education, conversion, creative'],['合作记录','Partnership record']]]),
    tool: checklist('AI 分类上线前复核', 'Before deploying an AI taxonomy', '10 项保证分类可解释和可维护。', 'Ten checks keep classification explainable and maintainable.', [['每个标签有一句清晰定义','Every label has a clear one-line definition'],['正例和反例都已保存','Positive and negative examples are saved'],['多标签与互斥规则明确','Multi-label and exclusivity rules are clear'],['证据窗口与最小样本已定义','Evidence window and minimum sample are defined'],['未知和无法判断可被保留','Unknown and indeterminate are allowed'],['40 个以上样本完成双人标注','At least 40 records are double-labeled'],['不一致样本用于修正规则','Disagreements update the rules'],['模型输出不会覆盖确认事实','Model output cannot overwrite confirmed facts'],['版本、负责人和日期已记录','Version, owner and date are recorded'],['复核周期和回滚路径存在','Review cycle and rollback path exist']]),
    sources: [sources.nistAiRmf],
  },
  'ai-creator-data-freshness': {
    deepDive: dive('不同字段需要不同新鲜度阈值', 'Different fields need different freshness thresholds', '达人数据不会同时过期。账号身份可能 180 天复核一次，报价与档期可能 30 天，受众地区和中位观看可能 60–90 天，广告权限则要在每次上线前实时检查。NIST AI RMF 强调持续测量与管理；把“最后确认日期”和“最大可接受年龄”并列，AI 才能在使用前识别过期字段。\n\n假设 500 位候选共有 4,000 个关键字段，其中 3,200 个在阈值内、500 个过期、300 个未知。字段新鲜率是 80%，但不能因此自动批准名单；如果 300 个未知集中在目标市场受众和权益状态，它们仍是阻断项。报告应同时显示整体比例和按字段风险分层。', 'Creator fields do not expire together. Identity may be reviewed every 180 days, rates and availability every 30, audience geography and median views every 60–90, while ad permission requires a live pre-launch check. NIST AI RMF emphasizes continuous measurement and management; pairing last-confirmed date with maximum age lets automation identify stale fields before use.\n\nIf 500 candidates have 4,000 critical fields, with 3,200 current, 500 stale and 300 unknown, field freshness is 80%. That does not approve the list if unknowns cluster in target-market audience or rights status. Show both the overall rate and field-level risk tiers.', ['nistAiRmf']),
    table: table('达人数据新鲜度策略', 'Creator data freshness policy', '示例阈值应按业务风险调整。', 'Adjust example thresholds to business risk.', [['字段','Field'],['示例最大年龄','Example maximum age'],['过期动作','Action when stale']], [[['身份与联系人','Identity and contact'],['180 天','180 days'],['重新验证','Reverify']], [['报价与档期','Rate and availability'],['30 天','30 days'],['外联确认','Confirm in outreach']], [['受众与表现','Audience and performance'],['60–90 天','60–90 days'],['请求新截图','Request fresh data']], [['权益与广告权限','Rights and ad access'],['上线时','At launch'],['阻断投放','Block delivery']]]),
    tool: checklist('AI 使用达人数据前检查', 'Before AI uses creator data', '8 项检查时间、来源和风险。', 'Eight checks cover time, source and risk.', [['每个关键字段有来源','Every critical field has a source'],['最后确认日期可用','Last-confirmed date is available'],['字段级新鲜度阈值已设置','Field-specific freshness limit is set'],['未知与零值严格分开','Unknown and zero are separate'],['过期字段不会自动参与排名','Stale fields do not auto-rank'],['高风险字段缺失会阻断动作','Missing high-risk fields block action'],['刷新操作保留旧值和时间','Refresh preserves prior value and date'],['批量刷新有抽样质量检查','Bulk refresh has sampled QA']]),
    sources: [sources.nistAiRmf],
  },
  'ai-campaign-postmortem': {
    deepDive: dive('复盘 AI 判断，而不是只复盘最终 KPI', 'Review AI decisions, not only final KPIs', 'AI 参与 Campaign 后，复盘要追踪每个关键建议的输入、输出、人工决定和结果。NIST AI RMF 将风险工作组织为 Govern、Map、Measure、Manage；对应到复盘，就是确认负责人和规则、描述使用场景、测量错误与人工改写，再决定保留、限制、暂停或重新设计。\n\n例如 AI 推荐 80 位达人，人工保留 50 位、外联 45 位、收到 14 个有效回复、签约 6 位。抽查发现 10 个推荐理由中 3 个引用过期内容，30% 的样本理由需要修正。即使最终 Campaign 达到 ROAS 目标，也不能忽略这项数据风险；它可能在下一次更大批次中放大。', 'When AI participates in a campaign, review every material recommendation through input, output, human decision and outcome. NIST AI RMF organizes risk work as Govern, Map, Measure and Manage. In a postmortem this means confirming ownership and rules, describing use, measuring errors and human edits, then deciding to retain, limit, pause or redesign.\n\nIf AI recommends 80 creators, humans retain 50, contact 45, receive 14 useful replies and sign six, then a sample finds three of ten rationales cite stale content, 30% of sampled rationales require correction. Even when campaign ROAS meets target, that data risk matters because it can scale in a larger batch.', ['nistAiRmf']),
    table: table('AI Campaign 复盘矩阵', 'AI campaign postmortem matrix', '业务结果和系统质量同时记录。', 'Record business outcomes and system quality together.', [['阶段','Stage'],['业务结果','Business outcome'],['AI 质量证据','AI quality evidence']], [[['发现','Discovery'],['候选进入率','Candidate acceptance'],['误收、漏选、过期数据','False inclusion, exclusion, stale data']], [['外联','Outreach'],['有效回复与签约','Useful replies and agreements'],['事实错误、人工改写','Factual errors, manual rewrites']], [['执行','Execution'],['准时、返工、风险','Timing, rework, risk'],['状态建议准确性','Status recommendation accuracy']], [['复盘','Review'],['收入、增量、学习','Revenue, lift, learning'],['保留 / 限制 / 暂停','Retain / limit / pause']]]),
    tool: checklist('AI Campaign 复盘议程', 'AI campaign postmortem agenda', '10 项把结果转成下一次可执行改进。', 'Ten items turn outcomes into next-run improvements.', [['确认 AI 参与的具体决策','Identify decisions where AI participated'],['保存使用的输入与版本','Preserve inputs and versions'],['比较建议、人工决定与结果','Compare recommendation, human decision and outcome'],['统计误收、漏选和无法验证','Count false inclusion, exclusion and unverifiable'],['统计事实错误与人工改写','Count factual errors and manual rewrites'],['分开业务 KPI 与系统质量','Separate business KPI from system quality'],['记录表现良好的反例','Preserve successful counterexamples'],['为每个问题指定负责人','Assign an owner to every issue'],['决定保留、限制、暂停或重做','Choose retain, limit, pause or redesign'],['下一批次设置可验证门槛','Set measurable gates for the next batch']]),
    sources: [sources.nistAiRmf],
  },
};
